
.phone {
  width: 100%;
  max-width: 460px;
  margin: 0 auto;
  background: var(--bg);
  border: 1px solid var(--line-2);
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: var(--font-ui);
}

/* 状态栏 */
.phone-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 14px;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
  background: #0e121b;
}

.status-model {
  letter-spacing: 1px;
  color: var(--accent);
}

.status-batt {
  letter-spacing: 1px;
}

/* 头部 */
.phone-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px;
  background: linear-gradient(135deg, #141a28 0%, #10141f 100%);
  border-bottom: 1px solid var(--line);
}

.header-title {
  display: flex;
  align-items: center;
  gap: 10px;
}

.header-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 8px var(--green);
}

.header-name {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 1px;
}

.header-sub {
  font-size: 11px;
  color: var(--muted);
  font-family: var(--font-mono);
  letter-spacing: 0.5px;
}

.header-state {
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1px;
  border: 1px solid;

  &.is-running {
    color: var(--green);
    border-color: var(--green);
    background: rgba(87, 217, 123, 0.1);
  }

  &.is-stopped {
    color: var(--red);
    border-color: var(--red);
    background: rgba(255, 92, 122, 0.1);
  }

  &.is-frozen {
    color: var(--blue);
    border-color: var(--blue);
    background: rgba(90, 167, 255, 0.1);
  }
}

/* 内容区 */
.phone-body {
  padding: 14px;
  background: var(--panel);
}

.pane {
  animation: fade-in 0.3s ease;
}

@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 底部导航 */
.phone-tabs {
  display: flex;
  border-top: 1px solid var(--line);
  background: #0e121b;
}

.tab-btn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 9px 0 8px;
  background: transparent;
  border: none;
  color: var(--muted);
  cursor: pointer;
  transition: color 0.2s;
  font-family: inherit;
}

.tab-btn:hover {
  color: var(--text);
}

.tab-btn.active {
  color: var(--accent);
}

.tab-icon {
  font-size: 14px;
  line-height: 1;
}

.tab-label {
  font-size: 11px;
  letter-spacing: 1px;
}
