
.panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.panel-title {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--text);
}

.panel-tag {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 2px;
  color: var(--muted);
}

.panel-desc {
  font-size: 12px;
  color: var(--muted);
  margin-top: -4px;
}

.state-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.state-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.2s;
  text-align: left;
  font-family: inherit;
}

.state-btn:hover {
  border-color: var(--line-2);
}

.state-btn.active {
  border-color: var(--accent);
  background: var(--accent-dim);
}

.state-icon {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-size: 15px;
}

.state-btn.运行中 .state-icon {
  background: rgba(87, 217, 123, 0.15);
  color: var(--green);
}

.state-btn.已停止 .state-icon {
  background: rgba(255, 92, 122, 0.15);
  color: var(--red);
}

.state-btn.已冻结 .state-icon {
  background: rgba(90, 167, 255, 0.15);
  color: var(--blue);
}

.state-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.state-label {
  font-size: 13px;
  font-weight: 700;
}

.state-desc {
  font-size: 11px;
  color: var(--muted);
}

.divider {
  height: 1px;
  background: var(--line);
  margin: 6px 0;
}

.battery {
  display: flex;
  align-items: center;
  gap: 10px;
}

.battery-track {
  flex: 1;
  height: 12px;
  border: 1px solid var(--line-2);
  border-radius: 6px;
  background: var(--panel-2);
  overflow: hidden;
}

.battery-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--green), var(--accent));
  transition: width 0.3s ease;

  &.low {
    background: linear-gradient(90deg, var(--red), var(--amber));
  }
}

.battery-value {
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 700;
  min-width: 44px;
  text-align: right;
}
